17|// CreateService 创建服务
18|func CreateService() (service *Service, err error) {
19|	service = &Service{}
20|
21|	// 1. 监听kafka
22|	service.disaptchRetMonitor = kafkawrap.CreateKafkaMonitor("", "", nil, service.dispatchRetHandler)
23|	// 2. 监听kafka
24|	service.cleanupRetMonitor = kafkawrap.CreateKafkaMonitor("", "", nil, service.cleanupRetHandler)
25|	// 3. 通知union_archiver_dispatch分发结果
26|	if err := kafkawrap.CreateSingletonKafkaProducer(kafkawrap.DefaultProducerConfig); err != nil {
27|		return nil, err
28|	}
29|	return
30|}
31|
32|// Service -
33|type Service struct {
34|	// 分发结果监听器
35|	disaptchRetMonitor *kafkawrap.KafkaMonitor
36|	// 区域清理结果监听器
37|	cleanupRetMonitor *kafkawrap.KafkaMonitor
38|}
39|
40|// Start 启动
41|func (s *Service) Start() {
42|	// 1. 启动事件监听
43|	s.disaptchRetMonitor.StartWithTopic(
44|		gopublic.GCM.F.Section("monitor").Key("kafka_topic_union_dispatch_result").MustString("union_dispatch_notify"),
45|		gopublic.GCM.F.Section("service").Key("appname").MustString("union-archiver-manager")+"-for-dispatch-result",
46|	)
47|	s.cleanupRetMonitor.StartWithTopic(
48|		gopublic.GCM.F.Section("monitor").Key("kafka_topic_area_cleanup_notify").MustString("area_cleanup_notify"),
49|		gopublic.GCM.F.Section("service").Key("appname").MustString("union-archiver-manager")+"-for-cleanup-result",
50|	)
51|}
52|
53|// Stop 停止
54|func (s *Service) Stop() {
55|	// 1. 启动事件监听
56|	s.disaptchRetMonitor.Stop()
57|	s.cleanupRetMonitor.Stop()
58|}
59|
60|func (s *Service) dispatchRetHandler(data []byte) {
61|	notify := new(model.AreaDispatchNotify)
62|	if err := json.Unmarshal(data, notify); err != nil {
63|		vlog.Errorf("Service.dispatchRetHandler(). unmarshal message failed. data(%s) errmsg:%s", string(data), err.Error())
64|	}
65|	vlog.Debugf("Service.dispatchRetHandler(). recv union dispatch notify success. task_id(%s) message(%s)", notify.TaskID, gopublic.ToJSON(notify))
66|
67|	if notify.Mode == model.AreaImport {
68|		doAreaImportResult(notify)
69|		return
70|	} else if notify.Mode == model.AreaLibImport {
71|		doAreaLibImportResult(notify)
72|		return
73|	}
74|
75|	// 获取分布式锁 更新MongoDB
76|	dlock := zkwrap.CreateDistributedLock(fmt.Sprintf("uss/%d-%d", notify.UUID, notify.UGID))
77|	if _, err := dlock.Lock(time.Duration(gopublic.GCM.F.Section("timeout").Key("acquire_flow_dlock").MustInt(3000)) * time.Millisecond); err != nil {
78|		vlog.Errorf("Service.dispatchRetHandler(). acquire dlock failed. uuid(%d) ugid(%d) errmsg:%s", notify.UUID, notify.UGID, err.Error())
79|		return
80|	}
81|	defer dlock.Unlock()
82|
83|	// 检查是否为存档备份任务
84|	bakinfo, _, err := QueryUnionArchiveBakupInfo(notify.UUID, notify.UGID, notify.DoneUnionVersion, notify.DstAreaType, notify.FlowID)
85|	if err == nil && bakinfo.State%dbwrap.BAKUPRETRY == dbwrap.BAKUPDOING {
86|		// 更新任务状态
87|		if notify.Errcode == 0 {
88|			bakinfo.State = dbwrap.BAKUPSUCC
89|		} else {
90|			bakinfo.State = dbwrap.BAKUPFAILED + bakinfo.State - dbwrap.BAKUPDOING
91|		}
92|		bakinfo.DoneAreaVersion = notify.DoneAreaVersion
93|		bakinfo.DoneTime = time.Now()
94|		bakinfo.UpdateTime = time.Now()
95|		bakinfo.ModifyTime = time.Now()
96|
97|		if _, err := UpdateUnionArchiveBakupInfo(bakinfo, notify.FlowID); err != nil {
98|			vlog.Errorf("Service.dispatchRetHandler(). update bak info failed. flow_id(%s) uuid(%d) ugid(%d) dst_area_type(%d) errmsg:%s", notify.FlowID, notify.UUID, notify.UGID, notify.DstAreaType, err.Error())
99|		}
100|	} else {
101|		topic := gopublic.GCM.F.Section("monitor").Key("kafka_topic_dispatch_result_notify").MustString("dispatch_result_notify")
102|		if err := kafkawrap.WriteKafkaJSON(topic, notify); err != nil {
103|			vlog.Errorf("Service.dispatchRetHandler(). report dispatch result failed. notify(%s) errmsg:%s", gopublic.ToJSON(notify), err.Error())
104|		} else {
105|			vlog.Errorf("Service.dispatchRetHandler(). report dispatch result success. notify(%s)", gopublic.ToJSON(notify))
106|		}
107|	}
108|
109|	// 1. 检查存档调度记录
110|	active, _, err := QueryAreaUserGameScheduleInfo(notify.UUID, notify.UGID, notify.DstAreaType, notify.FlowID)
111|	if err != nil {
112|		vlog.Errorf("Service.dispatchRetHandler(). query schedule info failed. uuid(%d) ugid(%d) dst_area_type(%d) errmsg:%s", notify.UUID, notify.UGID, notify.DstAreaType, err.Error())
113|		return
114|	}
115|
116|	// 当前duv大于分发duv，忽略请求
117|	if active.DoneUnionVersion > notify.DoneUnionVersion {
118|		vlog.Errorf("Service.dispatchRetHandler(). schedule version outdated. uuid(%d) ugid(%d) dst_area_type(%d) current_duv(%d) mode(%d)", notify.UUID, notify.UGID, notify.DstAreaType, active.DoneUnionVersion, notify.Mode)
119|		return
120|	}
121|
122|	if !((active.OpState == dbwrap.DISPATCHPREPARE && notify.Mode == model.AsynDispatch) || (active.OpState == dbwrap.SYNCDISPATCHPREPARE && notify.Mode == model.SyncDispatch)) {
123|		vlog.Errorf("Service.dispatchRetHandler(). schedule state not dispatch. uuid(%d) ugid(%d) dst_area_type(%d) current_op_state(%d) mode(%d)", notify.UUID, notify.UGID, notify.DstAreaType, active.OpState, notify.Mode)
124|		return
125|	}
126|
127|	if notify.Errcode != 0 {
128|		vlog.Errorf("Service.dispatchRetHandler(). union dispatch failed. uuid(%d) ugid(%d) dst_area_type(%d) done_union_version(%d) errcode(%d) errmsg:%s",
129|			notify.UUID, notify.UGID, notify.DstAreaType, notify.DoneUnionVersion, notify.Errcode, notify.Errmsg)
130|	}
131|
132|	// 2. 更新存档调度状态
133|	if _, err := UpdateUserGameScheduleInfo(
134|		active.UUGAID,
135|		&dbwrap.DBUnionUserGameScheduleInfo{
136|			UpdateTime: time.Now(),
137|			CreateTime: active.CreateTime,
138|			ModifyTime: active.ModifyTime,
139|			OpVersion:  active.OpVersion,
140|			OpState: func() dbwrap.ScheduleState {
141|				if notify.Mode == 1 {
142|					if notify.Errcode != 0 {
143|						return dbwrap.SYNCDISPATCHFAILED
144|					}
145|					// 实时迁移游戏中时，更新为GAMEPREPARE
146|					if _, err := LoadFlowCache(notify.FlowID); err == nil {
147|						return dbwrap.GAMEPREPARE
148|					}
149|					return dbwrap.SYNCDISPATCHDONE
150|				} else {
151|					if notify.Errcode != 0 {
152|						return dbwrap.DISPATCHFAILED
153|					}
154|					return dbwrap.DISPATCHDONE
155|				}
156|			}(),
157|			DoneAreaVersion: func() int {
158|				if notify.DoneAreaVersion != 0 &&
159|					notify.DoneAreaVersion != active.DoneAreaVersion {
160|					return notify.DoneAreaVersion
161|				}
162|				return 0
163|			}(),
164|			DoneUnionVersion: func() int {
165|				if notify.Errcode == 0 &&
166|					notify.DoneUnionVersion != active.DoneUnionVersion {
167|					return notify.DoneUnionVersion
168|				}
169|				return 0
