12|	"sync"
13|	"time"
14|
15|	"github.com/go-redis/redis/v8"
16|	"gitlab.vrviu.com/inviu/backend-go-public/gopublic"
17|	"gitlab.vrviu.com/inviu/backend-go-public/gopublic/vlog"
18|	"gitlab.vrviu.com/inviu/backend-go-public/gopublic/zkwrap"
19|)
20|
21|// CreateDClient 创建Data-Channel客户端
22|func CreateDClient() (client *DataChanClient, err error) {
23|	client = &DataChanClient{
24|		reqs: &sync.Map{},
25|	}
26|
27|	return client, nil
28|}
29|
30|// DataChanClient Data-Channel客户端
31|type DataChanClient struct {
32|	conn             *net.TCPConn
33|	reqs             *sync.Map
34|	cacherShootCache map[int]int              // 加权计算导入cacher-id缓存
35|	cacherShootMutex *sync.Mutex              // 加权计算导入cacher-id锁
36|	hb               *gopublic.RegularTrigger // heartbeat trigger
37|}
38|
39|// Init 初始化
40|func (c *DataChanClient) Init() error {
41|	if err := c.dial(
42|		gopublic.GCM.F.Section("outside").Key("data_channel_server_addr").String(),
43|		uint16(gopublic.GCM.F.Section("outside").Key("data_channel_server_port").MustInt(0)),
44|		time.Duration(gopublic.GCM.F.Section("timeout").Key("data_channel_server_dial_timeout").MustInt(3000))*time.Millisecond,
45|	); err != nil {
46|		vlog.Warnf("DataChanClient.Init(). dial to data-channel server failed, %s", err.Error())
47|	}
48|
49|	c.hb = gopublic.CreateRegularTrigger(
50|		"heartbeat-trigger",
51|		time.Duration(gopublic.GCM.F.Section("dclient").Key("heartbeat_period").MustInt(10000))*time.Millisecond,
52|		c.keepconn,
53|	)
54|	c.hb.Start()
55|	c.cacherShootMutex = new(sync.Mutex)
56|	c.cacherShootCache = make(map[int]int)
57|
58|	return nil
59|}
60|
61|// UnInit 去初始化
62|func (c *DataChanClient) UnInit() {
63|	if c.conn != nil {
64|		c.conn.Close()
65|		c.conn = nil
66|	}
67|
68|	if c.hb != nil {
69|		c.hb.Stop()
70|		c.hb = nil
71|	}
72|}
73|
74|// Dial 连接到服务端
75|func (c *DataChanClient) dial(addr string, port uint16, timeout time.Duration) error {
76|	d := net.Dialer{
77|		Timeout: timeout,
78|	}
79|
80|	conn, err := d.Dial("tcp", fmt.Sprintf("%s:%d", addr, port))
81|	if err != nil {
82|		return err
83|	}
84|
85|	v, ok := conn.(*net.TCPConn)
86|	if ok {
87|		c.conn = v
88|		c.conn.SetKeepAlive(true)
89|	} else {
90|		return errors.New("cast tcp conn failed")
91|	}
92|
93|	go c.recvloop()
94|
95|	return nil
96|}
97|
98|func (c *DataChanClient) keepconn() {
99|	if c.conn != nil {
100|		err := c.heartbeat()
101|		if err == nil {
102|			return
103|		}
104|
105|		c.conn.Close()
106|		vlog.Errorf("DataChanClient.keepconn(). heartbeat failed, try reconnect. errmsg:%s", err.Error())
107|	}
108|
109|	if err := c.dial(
110|		gopublic.GCM.F.Section("outside").Key("data_channel_server_addr").String(),
111|		uint16(gopublic.GCM.F.Section("outside").Key("data_channel_server_port").MustInt(0)),
112|		time.Duration(gopublic.GCM.F.Section("timeout").Key("data_channel_server_dial_timeout").MustInt(3000))*time.Millisecond,
113|	); err != nil {
114|		vlog.Errorf("DataChanClient.keepconn(). reconnect to data-channel server failed, %s", err.Error())
115|	}
116|}
117|
118|// send 发送请求
119|func (c *DataChanClient) send(requestID, cmdtype string, param map[string]interface{}) error {
120|	pairs := []string{
121|		fmt.Sprintf("cmd=%s", cmdtype),
122|		fmt.Sprintf("request_id=%s", requestID),
123|	}
124|
125|	for k, v := range param {
126|		pairs = append(pairs, fmt.Sprintf("%s=%v", k, v))
127|	}
128|
129|	data := []byte(strings.Join(pairs, "&") + "\n")
130|
131|	if c.conn == nil {
132|		return errors.New("not connect to server")
133|	}
134|
135|	_, err := c.conn.Write(data)
136|	if err != nil {
137|		vlog.Errorf("DataChanClient.send(). send messsage failed. data(%s) errmsg:%s", string(data), err.Error())
138|	} else {
139|		vlog.Debugf("DataChanClient.send(). send messsage success. data(%s)", string(data))
140|	}
141|
142|	return err
143|}
144|
145|// Recv 接收请求
146|func (c *DataChanClient) recv() (requestID, cmdtype string, param map[string]string, err error) {
147|	if c.conn == nil {
148|		return requestID, cmdtype, param, errors.New("not connect to server")
149|	}
150|
151|	data := make([]byte, 0)
152|	for {
153|		tmp := make([]byte, 1)
154|		if _, err := c.conn.Read(tmp); err != nil {
155|			return requestID, cmdtype, param, err
156|		}
157|
158|		if string(tmp) == "\n" {
159|			break
160|		} else {
161|			data = append(data, tmp...)
162|		}
163|	}
164|
165|	gopublic.PrintTraceLog("DataChanClient.recv(). recv message success. data(%s)", string(data))
166|
167|	param = make(map[string]string)
168|	for _, piece := range strings.Split(string(data), "&") {
169|		pair := strings.Split(piece, "=")
170|		if len(pair) != 2 {
171|			err = fmt.Errorf("parse piece failed:%s", piece)
172|			return
173|		}
174|
175|		if pair[0] == "cmd" {
176|			cmdtype = pair[1]
177|		} else if pair[0] == "request_id" {
178|			requestID = pair[1]
179|		} else {
180|			param[pair[0]] = pair[1]
181|		}
182|	}
183|
184|	return
185|}
186|
187|// recvloop 内部接受响应消息循环
188|func (c *DataChanClient) recvloop() error {
189|	for {
190|		if c.conn == nil {
191|			return errors.New("not connect to server")
192|		}
193|
194|		requestID, cmdtype, param, err := c.recv()
195|		if err != nil {
196|			vlog.Errorf("DataChanClient.recvloop(). recv message failed. errmsg:%s", err.Error())
197|			return fmt.Errorf("recv error:%s", err.Error())
198|		}
199|
200|		if v, ok := c.reqs.Load(requestID); ok {
201|			select {
202|			case v.(chan models.DataChanResonseAddTask) <- models.DataChanResonseAddTask{
203|				CmdType: cmdtype,
204|				TaksID: func() string {
205|					if v, ok := param["task_id"]; ok {
206|						return v
207|					}
208|					return ""
209|				}(),
210|				Result: func() int {
211|					if v, ok := param["result"]; ok {
212|						n, err := strconv.Atoi(v)
213|						if err != nil {
214|							return -1000
215|						}
216|						return n
217|					}
218|					return -1001
219|				}(),
220|			}:
221|			default:
222|			}
223|		} else {
224|			vlog.Warnf("DataChanClient.recvloop(). recv wild response. request_id(%s) cmd(%s) param(%s)", requestID, cmdtype, gopublic.ToJSON(param))
225|		}
226|	}
227|}
228|
