18|// ReloadConfig 重载配置文件
19|func ReloadConfig(ctx *fasthttp.RequestCtx) (errcode int, errmsg string, rspBody interface{}) {
20|	filename := string(ctx.QueryArgs().Peek("filename"))
21|	if filename == "" {
22|		filename = "./conf/app.conf"
23|	}
24|	diff, err := gopublic.GCM.Reload(filename)
25|	if err != nil {
26|		return -1, err.Error(), nil
27|	}
28|
29|	utils.LogicSvr.(*Service).InitTaskConfig()
30|	return 0, "ok", diff
31|}
32|
33|// Remove 请求迁移存档
34|func Remove(ctx *fasthttp.RequestCtx) (errcode int, errmsg string, rspBody interface{}) {
35|	var bargs model.RemoveQArgs
36|	if err := json.Unmarshal(ctx.Request.Body(), &bargs); err != nil {
37|		return 1101, err.Error(), nil
38|	}
39|
40|	// flow_id请求未传时本地生成
41|	if bargs.FlowID == "" {
42|		bargs.FlowID = fmt.Sprintf("%d_%d_%d_%d_%s", bargs.UUID, bargs.UGID, bargs.DstAreaType, bargs.DoneUnionVersion, gopublic.GenerateRandonString(12))
43|	} else if bargs.FlowID[0:2] == "0_" {
44|		bargs.FlowID = strings.Replace(bargs.FlowID, "0_", fmt.Sprintf("%d_", bargs.DstAreaType), 1)
45|	}
46|
47|	defer func() {
48|		if bargs.Mode == 1 {
49|			ReportGameFlowEvent(
50|				bargs.DstAreaType,
51|				bargs.FlowID,
52|				bargs.UUID,
53|				bargs.UGID,
54|				func() int {
55|					if errcode == 0 {
56|						return model.GerrSyncMovePrepareSucc
57|					}
58|					return model.GerrSyncMovePrepareFailed
59|				}(),
60|				func() string {
61|					if errcode == 0 {
62|						return "sync move prepare succ"
63|					}
64|					return fmt.Sprintf("sync move prepare failed:%s", errmsg)
65|				}())
66|		}
67|	}()
68|	// 1. 获取分布式锁
69|	dlock := zkwrap.CreateDistributedLock(fmt.Sprintf("uadispatch/%d_%d_%d", bargs.UUID, bargs.UGID, bargs.DoneUnionVersion))
70|
71|	if _, err := dlock.Lock(time.Duration(gopublic.GCM.F.Section("timeout").Key("acquire_flow_dlock").MustInt(3000)) * time.Millisecond); err != nil {
72|		vlog.Errorf("Remove(). acquire dlock failed. flow_id(%s) uuid(%d) ugid(%d) errmsg:%s", bargs.FlowID, bargs.UUID, bargs.UGID, err.Error())
73|		return model.ErrCodeDlockFailed, model.ErrDlockFailed.Error(), nil
74|	}
75|	defer dlock.Unlock()
76|
77|	// 2. 初始化task
78|	task, _, err := QueryRemoveTaskInfo(
79|		fmt.Sprintf("uuid__eq:%d$ugid__eq:%d$dst_area_type__eq:%d$done_union_version:%d", bargs.UUID, bargs.UGID, bargs.DstAreaType, bargs.DoneUnionVersion),
80|		bargs.FlowID)
81|	if err == nil {
82|		vlog.Errorf("Remove(). query remove task info exist. uuid(%d) ugid(%d) dst_area_type(%d) done_union_version(%d) model(%d)", bargs.UUID, bargs.UGID, bargs.DstAreaType, bargs.DoneUnionVersion, bargs.Mode)
83|	}
84|
85|	task.UUID = bargs.UUID
86|	task.UGID = bargs.UGID
87|	task.Identity = utils.LogicSvr.(*Service).Identity
88|	task.SrcAreaType = bargs.SrcAreaType
89|	task.DstAreaType = bargs.DstAreaType
90|	task.DoneUnionVersion = bargs.DoneUnionVersion
91|	task.CreateTime = time.Now()
92|	task.ModifyTime = time.Now()
93|	task.UpdateTime = time.Now()
94|	task.DispatchDoneTime = time.Unix(0, 0)
95|	task.CleanupDoneTime = time.Unix(0, 0)
96|
97|	// 3. 检查是否存在相同任务
98|	if _, err := LoadTaskInfoCache(bargs.UUID, bargs.UGID, bargs.DstAreaType, bargs.DoneUnionVersion); err == nil {
99|		// 实时+异步 异步+异步 忽略新任务
100|		if bargs.Mode != 1 {
101|			return model.ErrCodeOK, model.ErrTaskAlreadyRunning.Error(), nil
102|		}
103|		// 实时+实时 异步+实时 创建新任务
104|		vlog.Errorf("Remove(). task info exist. uuid(%d) ugid(%d) dst_area_type(%d) done_union_version(%d) model(%d)", bargs.UUID, bargs.UGID, bargs.DstAreaType, bargs.DoneUnionVersion, bargs.Mode)
105|	}
106|
107|	worker := CreateWorker(task, bargs.FlowID, bargs.Size, bargs.Mode)
108|	errcode, err = worker.Dispatch()
109|	switch err {
110|	case nil:
111|		return 0, "ok", model.UnionDispatchResult{TaskID: worker.TaskID}
112|	case model.ErrTaskWaiting:
113|		return errcode, err.Error(), nil
114|	default:
115|		return errcode, err.Error(), nil
116|	}
117|}
