30|// DataChanClient Data-Channel客户端
31|type DataChanClient struct {
32|	conn             *net.TCPConn
33|	reqs             *sync.Map
34|	cacherShootCache map[int]int              // 加权计算导入cacher-id缓存
35|	cacherShootMutex *sync.Mutex              // 加权计算导入cacher-id锁
36|	hb               *gopublic.RegularTrigger // heartbeat trigger
37|}
38|
39|// Init 初始化
40|func (c *DataChanClient) Init() error {
41|	if err := c.dial(
42|		gopublic.GCM.F.Section("outside").Key("data_channel_server_addr").String(),
43|		uint16(gopublic.GCM.F.Section("outside").Key("data_channel_server_port").MustInt(0)),
44|		time.Duration(gopublic.GCM.F.Section("timeout").Key("data_channel_server_dial_timeout").MustInt(3000))*time.Millisecond,
45|	); err != nil {
46|		vlog.Warnf("DataChanClient.Init(). dial to data-channel server failed, %s", err.Error())
47|	}
48|
49|	c.hb = gopublic.CreateRegularTrigger(
50|		"heartbeat-trigger",
51|		time.Duration(gopublic.GCM.F.Section("dclient").Key("heartbeat_period").MustInt(10000))*time.Millisecond,
52|		c.keepconn,
53|	)
54|	c.hb.Start()
55|	c.cacherShootMutex = new(sync.Mutex)
56|	c.cacherShootCache = make(map[int]int)
57|
58|	return nil
59|}
60|
61|// UnInit 去初始化
62|func (c *DataChanClient) UnInit() {
63|	if c.conn != nil {
64|		c.conn.Close()
65|		c.conn = nil
66|	}
67|
68|	if c.hb != nil {
69|		c.hb.Stop()
70|		c.hb = nil
71|	}
