74|// Dial 连接到服务端
75|func (c *DataChanClient) dial(addr string, port uint16, timeout time.Duration) error {
76|	d := net.Dialer{
77|		Timeout: timeout,
78|	}
79|
80|	conn, err := d.Dial("tcp", fmt.Sprintf("%s:%d", addr, port))
81|	if err != nil {
82|		return err
83|	}
84|
85|	v, ok := conn.(*net.TCPConn)
86|	if ok {
87|		c.conn = v
88|		c.conn.SetKeepAlive(true)
89|	} else {
90|		return errors.New("cast tcp conn failed")
91|	}
92|
93|	go c.recvloop()
94|
95|	return nil
96|}
97|
98|func (c *DataChanClient) keepconn() {
99|	if c.conn != nil {
100|		err := c.heartbeat()
101|		if err == nil {
102|			return
103|		}
104|
105|		c.conn.Close()
106|		vlog.Errorf("DataChanClient.keepconn(). heartbeat failed, try reconnect. errmsg:%s", err.Error())
107|	}
108|
109|	if err := c.dial(
110|		gopublic.GCM.F.Section("outside").Key("data_channel_server_addr").String(),
111|		uint16(gopublic.GCM.F.Section("outside").Key("data_channel_server_port").MustInt(0)),
112|		time.Duration(gopublic.GCM.F.Section("timeout").Key("data_channel_server_dial_timeout").MustInt(3000))*time.Millisecond,
113|	); err != nil {
114|		vlog.Errorf("DataChanClient.keepconn(). reconnect to data-channel server failed, %s", err.Error())
115|	}
116|}
