118|// send 发送请求
119|func (c *DataChanClient) send(requestID, cmdtype string, param map[string]interface{}) error {
120|	pairs := []string{
121|		fmt.Sprintf("cmd=%s", cmdtype),
122|		fmt.Sprintf("request_id=%s", requestID),
123|	}
124|
125|	for k, v := range param {
126|		pairs = append(pairs, fmt.Sprintf("%s=%v", k, v))
127|	}
128|
129|	data := []byte(strings.Join(pairs, "&") + "\n")
130|
131|	if c.conn == nil {
132|		return errors.New("not connect to server")
133|	}
134|
135|	_, err := c.conn.Write(data)
136|	if err != nil {
137|		vlog.Errorf("DataChanClient.send(). send messsage failed. data(%s) errmsg:%s", string(data), err.Error())
138|	} else {
139|		vlog.Debugf("DataChanClient.send(). send messsage success. data(%s)", string(data))
140|	}
141|
142|	return err
143|}
144|
145|// Recv 接收请求
146|func (c *DataChanClient) recv() (requestID, cmdtype string, param map[string]string, err error) {
147|	if c.conn == nil {
148|		return requestID, cmdtype, param, errors.New("not connect to server")
149|	}
150|
151|	data := make([]byte, 0)
152|	for {
153|		tmp := make([]byte, 1)
154|		if _, err := c.conn.Read(tmp); err != nil {
155|			return requestID, cmdtype, param, err
156|		}
157|
158|		if string(tmp) == "\n" {
159|			break
160|		} else {
161|			data = append(data, tmp...)
162|		}
163|	}
164|
165|	gopublic.PrintTraceLog("DataChanClient.recv(). recv message success. data(%s)", string(data))
166|
167|	param = make(map[string]string)
168|	for _, piece := range strings.Split(string(data), "&") {
169|		pair := strings.Split(piece, "=")
170|		if len(pair) != 2 {
171|			err = fmt.Errorf("parse piece failed:%s", piece)
172|			return
173|		}
174|
175|		if pair[0] == "cmd" {
176|			cmdtype = pair[1]
177|		} else if pair[0] == "request_id" {
178|			requestID = pair[1]
179|		} else {
180|			param[pair[0]] = pair[1]
181|		}
182|	}
183|
184|	return
185|}
