409|func (s *Service) startRemove(start, end time.Time, tasks []model.UGTask) {
410|
411|	for _, task := range tasks {
412|		if _, ok := s.RemoveURCodes[task.URCode]; !ok {
413|			vlog.Infof("Service.startRemove(). urcode(%d) not need start task(%s)", task.URCode, gopublic.ToJSON(task))
414|			continue
415|		}
416|		go func(task model.UGTask) {
417|			// 获取各区域迁移UG, 启动迁移
418|			areaUGs, _, err := QueryAreaUG(start, end, task.SrcAreaType, task.TotalTaskNum, task.URCode, s.WhiteUgid, s.BlackUgid)
419|			if err != nil {
420|				vlog.Errorf("Service.startRemove(). query area ug failed. errmsg:%s", err.Error())
421|				return
422|			}
423|			vlog.Infof("Service.startRemove(). task(%s) count(%d)", gopublic.ToJSON(task), len(areaUGs))
424|			if len(task.DstTask) == 0 {
425|				return
426|			}
427|			areataskindex := 0
428|			done := false
429|			for _, areaUG := range areaUGs {
430|			RESET:
431|				if areataskindex >= len(task.DstTask) {
432|					areataskindex = 0
433|					if done {
434|						break
435|					}
436|					done = true
437|				}
438|				if task.DstTask[areataskindex].DstTaskNum == 0 {
439|					areataskindex++
440|					goto RESET
441|				}
442|				// 获取此UG的版本
443|				flow, _, err := QueryUGLatestFlow(start, end, areaUG.UUID, areaUG.UGID, areaUG.SrcAreaType, task.URCode)
444|				if err != nil {
445|					vlog.Errorf("Service.startRemove(). query area ug flow failed. errmsg:%s", err.Error())
446|					return
447|				} else if len(flow) == 0 {
448|					vlog.Errorf("Service.startRemove(). query area ug flow not exist.")
449|					return
450|				}
451|				// 请求迁移
452|				flowID := fmt.Sprintf("%d_%d_%d_%d_%s", areaUG.UUID, areaUG.UGID, task.DstTask[areataskindex].DstAreaType, flow[0].EndDoneUnionVersion, gopublic.GenerateRandonString(12))
453|				if _, err := RequestRemoveArchiver(map[string]interface{}{
454|					"uuid":               areaUG.UUID,
455|					"ugid":               areaUG.UGID,
456|					"src_area_type":      areaUG.SrcAreaType,
457|					"dst_area_type":      task.DstTask[areataskindex].DstAreaType,
458|					"done_union_version": flow[0].EndDoneUnionVersion,
459|					"flow_id":            flowID,
460|					"size":               flow[0].Size,
461|				}, flowID); err != nil {
462|					vlog.Errorf("Service.startRemove(). request remove archiver failed. errmsg:%s", err.Error())
463|				}
464|				// 更新此区域剩余任务数
465|				task.DstTask[areataskindex].DstTaskNum--
466|				// 处理下一个区域
467|				areataskindex++
468|				done = false
469|			}
470|		}(task)
